//! PoC 5: heads generated by Anny, rendered by the same wgpu pipeline.
//!
//! 1. `anny_sheet jobs [--calibrated | --anny-calibrated] [--face-age]` writes `out/tmp/anny/jobs.json`: for each sheet
//!    genome and age, Anny phenotypes (ancestry, muscle, weight) and local
//!    changes (shape genes and age rules, by MakeHuman target name).
//! 2. `python anny/anny_heads.py out/tmp/anny` evaluates Anny for each job.
//! 3. `anny_sheet render` renders the Anny heads: an age sheet, a MakeHuman vs
//!    Anny comparison, measurements, and photo-finish inputs.

use glam::Vec3;
use regen_faces_poc::age::{AgeState, SHEET_AGES};
use regen_faces_poc::cards::Style;
use regen_faces_poc::face::FaceBuilder;
use regen_faces_poc::genome::Genome;
use regen_faces_poc::img::{contact_sheet, Rgba};
use regen_faces_poc::measure::{Landmarks, NORMS};
use regen_faces_poc::pools::nation;
use regen_faces_poc::render::{Camera, Renderer, SIZE};
use std::path::Path;

const SHEET: [(&str, u64); 6] = [("NHV", 6), ("CVD", 4), ("CVD", 1), ("KSI", 2), ("NHV", 13), ("NHV", 20)];
const DIR: &str = "out/tmp/anny";

fn stem(code: &str, seed: u64, years: f32) -> String {
    format!("{code}_{seed}_age{}", years as u32)
}

fn jobs(fb: &mut FaceBuilder, calibrated: bool, face_age: bool, anny_cal: bool) {
    fb.base.calibrate = calibrated;
    let mut out = Vec::new();
    for (code, seed) in SHEET {
        let g = Genome::generate(seed, nation(code).unwrap(), 2004);
        for years in SHEET_AGES {
            let age = AgeState::new(&g, years);
            let local: serde_json::Map<String, serde_json::Value> = fb
                .base
                .weights_for(&g, &age)
                .into_iter()
                .filter(|(n, w)| !n.starts_with("macrodetails") && w.abs() > 1e-4)
                .fold(serde_json::Map::new(), |mut m, (n, w)| {
                    let prev = m.get(&n).and_then(|v| v.as_f64()).unwrap_or(0.0);
                    m.insert(n, serde_json::json!(prev + w as f64));
                    m
                });
            // Anny's age anchors are linear: child 1/9, young 5/9, old 1. Our
            // face-age rule (child/young/old weights) converts to one value.
            let anny_age = if age.mh_child > 0.0 {
                5.0 / 9.0 - age.mh_child * 4.0 / 9.0
            } else {
                5.0 / 9.0 + age.mh_old * 4.0 / 9.0
            };
            out.push(serde_json::json!({
                "id": stem(code, seed, years),
                "years": years,
                "anny_age": if face_age { serde_json::json!(anny_age) } else { serde_json::Value::Null },
                "phenotypes": {
                    "gender": 1.0,
                    "muscle": age.muscle,
                    "weight": age.weight,
                    "height": 0.5,
                    "african": g.mh_mix[0],
                    "asian": g.mh_mix[1],
                    "caucasian": g.mh_mix[2],
                },
                "local": local,
                "anny_calibration": anny_cal,
            }));
        }
    }
    std::fs::create_dir_all(DIR).unwrap();
    std::fs::write(format!("{DIR}/jobs.json"), serde_json::to_string_pretty(&out).unwrap()).unwrap();
    eprintln!("wrote {} jobs to {DIR}/jobs.json (calibrated: {calibrated}, face age rule: {face_age})", out.len());
}

fn load_positions(id: &str) -> Vec<Vec3> {
    let bytes = std::fs::read(format!("{DIR}/{id}.f32")).expect("run anny/anny_heads.py first");
    let f: &[f32] = bytemuck::cast_slice(&bytes);
    f.chunks(3).map(|c| Vec3::new(c[0], c[1], c[2])).collect()
}

fn render(fb: &mut FaceBuilder, tag: &str) {
    let r = Renderer::new();
    let cam = Camera::portrait(12.0);
    let lm = Landmarks::find(&mut fb.base);
    let mut rows = Vec::new();
    let mut compare = Vec::new();
    let mut labels = Vec::new();
    let mut manifest = String::new();
    let mut meas_anny = Vec::new();
    let mut meas_mh = Vec::new();
    for (code, seed) in SHEET {
        let g = Genome::generate(seed, nation(code).unwrap(), 2004);
        let style = Style::for_genome(&g);
        labels.push(format!("{code} SEED {seed}\n{}", style.label()));
        let mut row = Vec::new();
        let mut cmp = Vec::new();
        for years in SHEET_AGES {
            let id = stem(code, seed, years);
            let age = AgeState::new(&g, years);
            let head = fb.base.build_from_positions(load_positions(&id));
            if years == 24.0 {
                meas_anny.push((format!("{code}{seed}"), lm.measure(&head)));
                meas_mh.push(lm.measure(&fb.head(&g, &age)));
            }
            let draws = fb.portrait_from(&g, &age, &head, Some(style));
            let f = r.render(&draws, &cam);
            let img = Rgba::from_raw(SIZE, SIZE, f.colour);
            if [19.0, 30.0, 60.0].contains(&years) {
                let depth = Rgba::from_raw(SIZE, SIZE, f.depth);
                img.save_png(Path::new(&format!("{DIR}/finish_inputs/{id}.png")));
                depth.save_png(Path::new(&format!("{DIR}/finish_inputs/{id}_depth.png")));
                let eyes = format!("{:?}", g.eye_colour).to_lowercase();
                manifest += &format!(
                    "{DIR}/finish_inputs/{id}.png,{DIR}/finish_inputs/{id}_depth.png,{DIR}/finished/{id}.png,embeds_age{}_{eyes}\n",
                    years as u32
                );
                let mh = Rgba::load_png(Path::new(&format!("out/tmp/poc2/{id}.png")));
                cmp.push(mh);
                cmp.push(img.clone());
            }
            row.push(img);
        }
        rows.push(row);
        compare.push(cmp);
    }
    std::fs::write(format!("{DIR}/pairs.csv"), manifest).unwrap();
    let cols: Vec<String> = SHEET_AGES.iter().map(|a| format!("AGE {a}")).collect();
    contact_sheet(&rows, 240, &cols, &labels).save_jpeg(Path::new(&format!("out/poc5_anny_age_sheet{tag}.jpg")), 80);
    let cols: Vec<String> = [19, 30, 60].iter().flat_map(|a| [format!("{a} MAKEHUMAN"), format!("{a} ANNY")]).collect();
    contact_sheet(&compare, 240, &cols, &labels).save_jpeg(Path::new(&format!("out/poc5_makehuman_vs_anny{tag}.jpg")), 80);

    let mut t = format!("{:24} {:>6} {:>6}", "measure at 24 (mm)", "NAW", "AFR");
    for (n, _) in &meas_anny {
        t += &format!(" {:>8} {:>8}", format!("{n}MH"), format!("{n}AN"));
    }
    t += "\n";
    for (k, norm) in NORMS.iter().enumerate() {
        t += &format!("{:24} {:6.1} {:6.1}", norm.name, norm.naw, norm.african);
        for (i, (_, m)) in meas_anny.iter().enumerate() {
            t += &format!(" {:8.1} {:8.1}", meas_mh[i][k], m[k]);
        }
        t += "\n";
    }
    std::fs::write(format!("out/poc5_measurements{tag}.txt"), &t).unwrap();
    print!("{t}");
}

fn main() {
    let mut fb = FaceBuilder::new().expect("MakeHuman assets (run scripts/fetch_makehuman.sh)");
    match std::env::args().nth(1).as_deref() {
        Some("jobs") => {
            let has = |f: &str| std::env::args().any(|a| a == f);
            jobs(&mut fb, has("--calibrated"), has("--face-age"), has("--anny-calibrated"))
        }
        Some("landmarks") => {
            let lm = Landmarks::find(&mut fb.base);
            let defs: Vec<serde_json::Value> = lm
                .definitions()
                .iter()
                .zip(NORMS.iter())
                .map(|((axis, a, b), n)| {
                    serde_json::json!({"name": n.name, "axis": axis, "a": a, "b": b,
                                       "naw": n.naw, "african": n.african, "sd": n.sd})
                })
                .collect();
            std::fs::create_dir_all(DIR).unwrap();
            std::fs::write(format!("{DIR}/landmarks.json"), serde_json::to_string_pretty(&defs).unwrap()).unwrap();
            eprintln!("wrote {DIR}/landmarks.json");
        }
        Some("finish") => {
            // MakeHuman-direct v2 finish vs Anny finish, ages 30 and 60.
            let mut rows = Vec::new();
            let mut labels = Vec::new();
            for (code, seed) in SHEET {
                let mut row = Vec::new();
                for years in [30.0, 60.0] {
                    let id = stem(code, seed, years);
                    row.push(Rgba::load_png(Path::new(&format!("out/tmp/finished/{id}.png"))));
                    row.push(Rgba::load_png(Path::new(&format!("{DIR}/finish_inputs/{id}.png"))));
                    row.push(Rgba::load_png(Path::new(&format!("{DIR}/finished/{id}.png"))));
                }
                rows.push(row);
                labels.push(format!("{code} SEED {seed}"));
            }
            let cols = ["30 MH FINISH", "30 ANNY", "30 ANNY FIN", "60 MH FINISH", "60 ANNY", "60 ANNY FIN"].map(String::from);
            contact_sheet(&rows, 240, &cols, &labels).save_jpeg(Path::new("out/poc5_finish_compare.jpg"), 80);
        }
        Some("render") => render(&mut fb, &std::env::args().skip_while(|a| a != "--tag").nth(1).unwrap_or_default()),
        _ => eprintln!("usage: anny_sheet jobs [--calibrated | --anny-calibrated] [--face-age] | anny_sheet landmarks | anny_sheet render [--tag NAME]"),
    }
}
